import type { Question } from '../questions';

export const UPSC_GEO_SCIENTIST_2027_GEOLOGY_HYDROGEOLOGY_PAPER_2_GEOLOGY_HYDROGEOLOGY_1: Question[] = [
  { id: 'b14-002-geo-q001', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology', difficulty: 'medium', question: 'A stream falls 120 m over a map distance of 6 km. Its average longitudinal gradient is:', options: ['5 m/km', '20 m/km', '50 m/km', '720 m/km'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Average gradient=120/6=20 m per kilometre.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q002', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology — Fluvial Incision', difficulty: 'medium', question: 'A river flowing across bedrock is suddenly lowered at its downstream base level by tectonic uplift of the coast. A sharp break in channel slope develops and migrates progressively upstream. Which process is being observed?', options: ['Lateral migration of a point bar during aggradation', 'Formation of a marine tombolo by longshore drift', 'Development of a drumlin beneath stagnant ice', 'Headward migration of a knickpoint during renewed incision'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A fall in base level creates a new, steeper downstream profile. The resulting knickpoint commonly retreats upstream as the river incises toward a new graded profile.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q003', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology — Drainage Patterns', difficulty: 'medium', question: 'On a broad surface underlain by nearly horizontal, uniformly resistant rock with little structural control, tributaries join the main stream in an irregular branching network. The expected drainage pattern is:', options: ['Trellis', 'Radial', 'Dendritic', 'Annular'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Dendritic drainage develops where lithology and structure offer roughly uniform resistance, so stream directions are not strongly structurally guided.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q004', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology — Meander Evolution', difficulty: 'medium', question: 'A meandering river cuts through the narrow neck between two adjacent bends during a flood. Sediment then seals the abandoned loop from the main channel. The resulting landform is a:', options: ['Oxbow lake', 'Alluvial fan', 'Eskers', 'Wave-cut platform'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Neck cutoff shortens the river course; deposition at the old entrances isolates the former meander loop as an oxbow lake.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q005', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology — River Terraces', difficulty: 'hard', question: 'Along both sides of a valley, flat gravel-covered benches occur at nearly the same elevation well above the modern floodplain. The simplest geomorphic interpretation is that they are remnants of:', options: ['A single active floodplain currently built by overbank deposition', 'A recent coastal beach ridge formed at sea level', 'An older valley floor left stranded by subsequent river incision', 'A lava plateau unrelated to the drainage system'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Paired terraces at similar heights commonly represent a former floodplain or valley floor dissected after renewed downcutting.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q006', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology', difficulty: 'medium', question: 'A drainage basin of 30 km² contains 45 km of mapped channel length. Its drainage density is:', options: ['1.5 km/km²', '0.67 km/km²', '15 km/km²', '75 km/km²'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Drainage density is total channel length divided by basin area: 45/30=1.5 km/km².', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q007', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology — Aeolian Erosion', difficulty: 'medium', question: 'In a desert pavement, exposed pebbles show polished planar faces meeting along sharp edges, with the faces oriented toward prevailing sand-laden winds. This texture most strongly indicates:', options: ['Solution weathering beneath a soil profile', 'Wind abrasion producing ventifacts', 'Glacial plucking under moving ice', 'Wave quarrying in the surf zone'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Wind-driven sand abrades exposed stones and can cut polished facets and keels characteristic of ventifacts.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q008', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology — Glacial Deposits', difficulty: 'hard', question: 'A valley section exposes an unsorted, unstratified mixture from clay size to boulders resting directly on striated bedrock. No consistent current bedding is present. The deposit was most likely laid down:', options: ['By a braided river as well-sorted outwash', 'By wind as loess', 'By a deep marine turbidity current', 'Directly by glacier ice as till'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Direct glacial deposition produces till, characteristically very poorly sorted and commonly unstratified, unlike meltwater outwash.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q009', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology — Karst', difficulty: 'medium', question: 'A landscape contains closed depressions, disappearing streams and caves, while surface drainage is sparse. Which bedrock setting best explains the assemblage?', options: ['Massive fresh basalt with no fractures', 'Thick, soluble limestone with well-developed joints', 'Unconsolidated dune sand above an impermeable floor', 'Unjointed quartzite with negligible solution'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Karst develops where groundwater can circulate through fractures in soluble carbonate rock, enlarging conduits and diverting drainage underground.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q010', section: 'Geology/Hydrogeology Paper II', topic: 'Physical Geology & Geomorphology — Alluvial Fans', difficulty: 'medium', question: 'Across an alluvial fan built at a mountain front, field mapping shows boulder-rich proximal channels and sandier, finer deposits toward the toe. The dominant reason for this outward fining is:', options: ['Flow loses competence as it spreads and decelerates away from the fan apex', 'Sediment becomes progressively more metamorphosed toward the toe', 'Groundwater dissolves only the coarse grains at the apex', 'Wind selectively adds boulders to the proximal fan'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'As confined flow exits the mountain valley and spreads over the fan, velocity and transport competence decrease, causing coarse material to be deposited first.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q011', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics', difficulty: 'hard', question: 'A planar bed drops 100 m vertically over 173.2 m measured horizontally in the true dip direction. Its dip is closest to:', options: ['15°', '45°', '60°', '30°'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'tan(dip)=100/173.2≈0.577, giving about 30°.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q012', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics — Strike and Dip', difficulty: 'medium', question: 'A planar bed has strike 090° and dip 30° toward the south. In which horizontal direction is the line of maximum downward slope on the bed?', options: ['East', 'South', 'West', 'North'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Dip direction is perpendicular to strike and points down the plane. With an east-west strike and stated southerly dip, the maximum downslope direction is south.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q013', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics — Normal Faulting', difficulty: 'medium', question: 'Across a mapped fault, a marker bed is displaced so that the hanging wall is down relative to the footwall. The regional regime most consistent with this geometry is:', options: ['Horizontal shortening', 'Pure magmatic inflation with no strain', 'Regional compression only', 'Crustal extension'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Hanging-wall-down displacement defines a normal fault, which is the characteristic brittle structure of extensional regimes.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q014', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics — Thrust Tectonics', difficulty: 'hard', question: 'A low-angle fault places older strata structurally above much younger strata and is accompanied by repeated stratigraphic sections. Which tectonic interpretation is strongest?', options: ['Normal faulting produced by regional extension', 'Thrust faulting produced by crustal shortening', 'Strike-slip faulting with no vertical component', 'Synsedimentary compaction without faulting'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Low-angle reverse displacement and repetition of stratigraphy are classic evidence of thrusting in a compressional setting.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q015', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics — Map Patterns', difficulty: 'medium', question: 'On a topographic map, the trace of a sedimentary contact closely follows the same elevation contour around hills and valleys. What attitude of the contact is most consistent with that pattern?', options: ['Approximately horizontal', 'Vertical', 'Steeply dipping north', 'Steeply dipping east'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A horizontal geological surface intersects topography at essentially a constant elevation, so its map trace parallels contour lines.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q016', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics', difficulty: 'hard', question: 'A bed has true dip 30°. A vertical section is cut at 30° to the strike. The apparent dip is closest to:', options: ['16.1°', '8.2°', '30.0°', '49.1°'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'tan δa=tan δ × sin 30°=0.577×0.5=0.2887, so δa≈16.1°.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q017', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics — Fold Geometry', difficulty: 'medium', question: 'In a sequence whose facing direction is known, the oldest beds occur along the fold core and the two limbs dip away from the axial trace. The structure is a:', options: ['Syncline', 'Anticline', 'Monocline', 'Graben'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'An anticline has older strata in its core when the sequence is not overturned, and its limbs dip away from the axial region.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q018', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics — Stress and Fractures', difficulty: 'hard', question: 'Two conjugate sets of shear fractures form in a brittle rock under compression. In the idealized Mohr-Coulomb geometry, the maximum compressive principal stress direction approximately:', options: ['Lies exactly along either shear fracture set', 'Is always vertical regardless of loading', 'Bisects the acute angle between the conjugate shear sets', 'Bisects the obtuse angle only and cannot bisect the acute angle'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Conjugate shear planes form symmetrically about the σ1 direction; σ1 approximately bisects their acute angle, with the exact angle governed by friction.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q019', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics — Strike-Slip Faults', difficulty: 'medium', question: 'A stream channel crossing a near-vertical fault is offset so that the far-side segment appears shifted to the right when viewed across the fault. The fault has:', options: ['Left-lateral (sinistral) slip', 'Only normal dip-slip', 'Only reverse dip-slip', 'Right-lateral (dextral) slip'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'By convention, a strike-slip fault is dextral if the block across the fault appears displaced to the observer’s right.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q020', section: 'Geology/Hydrogeology Paper II', topic: 'Structural Geology & Tectonics — Boudinage', difficulty: 'medium', question: 'A competent quartz layer enclosed in weaker schist is broken into regularly spaced, sausage-shaped segments while the surrounding rock remains ductile. The structure records dominant:', options: ['Shortening parallel to the competent layer only', 'Extension parallel to the competent layer', 'Hydrostatic compaction with no differential strain', 'Vertical sediment loading before lithification'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Boudins form when a competent layer is stretched parallel to its length within a more ductile matrix.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q021', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography', difficulty: 'hard', question: 'For first-order X-ray diffraction, Cu Kα radiation of wavelength 1.54 Å gives a peak at θ=30°. The corresponding d-spacing is:', options: ['1.54 Å', '0.77 Å', '2.67 Å', '3.08 Å'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Bragg\'s law nλ=2d sinθ gives d=1.54/(2×0.5)=1.54 Å.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q022', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography — Mohs Hardness', difficulty: 'medium', question: 'An unknown mineral scratches ordinary glass but is scratched by quartz. Its Mohs hardness is most plausibly:', options: ['About 6', 'About 2', 'About 4', 'Greater than 8'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Window glass is about 5.5 on Mohs scale and quartz is 7. A mineral that scratches glass but is scratched by quartz lies between them, near hardness 6.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q023', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography — Carbonate Identification', difficulty: 'medium', question: 'A colourless mineral with perfect rhombohedral cleavage effervesces vigorously when a drop of dilute HCl is placed on a fresh surface. The mineral is most likely:', options: ['Quartz', 'Orthoclase', 'Calcite', 'Gypsum'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Calcite has rhombohedral cleavage and reacts readily with dilute hydrochloric acid because it is calcium carbonate.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q024', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography — Crystal Systems', difficulty: 'medium', question: 'A crystal unit cell is described by a=b=c and α=β=γ=90°. To which crystal system does this metric symmetry belong?', options: ['Cubic (isometric)', 'Tetragonal', 'Orthorhombic', 'Monoclinic'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The cubic system has three equal crystallographic axes mutually perpendicular. Tetragonal has a=b≠c, while orthorhombic has three unequal perpendicular axes.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q025', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography — Optical Mineralogy', difficulty: 'hard', question: 'In a standard thin section under crossed polars, a colourless grain shows very high-order interference colours and rhombohedral cleavage. Which identification is most consistent?', options: ['Quartz', 'Feldspar', 'Calcite', 'Garnet'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Calcite combines rhombohedral cleavage with very high birefringence, producing high-order interference colours. Quartz and feldspar have much lower birefringence, while garnet is isotropic.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q026', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography', difficulty: 'medium', question: 'A mineral scratches apatite but is scratched by orthoclase. Its Mohs hardness is most likely near:', options: ['3.0', '5.5', '7.0', '9.0'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Apatite is hardness 5 and orthoclase 6, so an intermediate hardness is about 5.5.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q027', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography — Plagioclase Composition', difficulty: 'medium', question: 'A plagioclase analysis is reported as An70. Which statement is correct?', options: ['It contains 70 wt% quartz', 'About 70 mol% of the feldspar component is anorthite, so the plagioclase is relatively Ca-rich', 'It is 70 mol% orthoclase and therefore K-rich', 'It must be pure albite with no Ca component'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'An denotes the anorthite component CaAl2Si2O8 in the albite-anorthite solid solution. An70 is therefore calcic plagioclase.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q028', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography — Feldspar Twinning', difficulty: 'medium', question: 'Under crossed polars, a potassium feldspar grain displays a distinctive cross-hatched or tartan twinning pattern. This most strongly indicates:', options: ['Sanidine', 'Calcite', 'Olivine', 'Microcline'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Microcline commonly shows combined albite and pericline twinning that gives a diagnostic cross-hatched appearance.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q029', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography — Silicate Structures', difficulty: 'medium', question: 'Muscovite splits readily into very thin elastic sheets along one direction. Which aspect of its crystal structure best explains this perfect basal cleavage?', options: ['Equal strong bonding in all three dimensions', 'A framework made only of isolated silica tetrahedra', 'Strong bonding within silicate sheets but much weaker bonding between adjacent sheets', 'A metallic lattice with no silicate sheets'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Micas are sheet silicates. Strong intralayer bonds and weaker interlayer bonds make separation easy parallel to the basal plane.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q030', section: 'Geology/Hydrogeology Paper II', topic: 'Mineralogy & Crystallography — Optical Isotropy', difficulty: 'medium', question: 'A euhedral mineral in thin section remains dark through a full 360° stage rotation under crossed polars and belongs to the cubic system. Which mineral is a plausible identification?', options: ['Garnet', 'Quartz', 'Calcite', 'Biotite'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Cubic minerals are optically isotropic. Garnet is cubic and remains extinct under crossed polars, whereas quartz, calcite and biotite are anisotropic.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q031', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology', difficulty: 'medium', question: 'A volcanic rock is aphanitic, dark coloured and contains abundant calcic plagioclase and pyroxene. The most likely rock name is:', options: ['basalt', 'rhyolite', 'granite', 'quartzite'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A fine-grained mafic volcanic assemblage of calcic plagioclase and pyroxene is basaltic.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q032', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology — Fractional Crystallization', difficulty: 'medium', question: 'A basaltic magma crystallizes early olivine and pyroxene, and those crystals are efficiently removed from contact with the melt. The residual liquid will generally evolve toward:', options: ['Lower SiO₂ because silica is removed exclusively by olivine', 'Higher SiO₂ and incompatible-element concentrations', 'The exact composition of the original mantle with no change', 'Pure metallic iron'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Removal of early mafic minerals leaves a melt enriched in components not strongly incorporated into those crystals, commonly making it more evolved and silica-rich.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q033', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology — Volcanic-Plutonic Equivalents', difficulty: 'medium', question: 'A felsic magma cools slowly at depth and forms a coarse-grained rock dominated by quartz and K-feldspar. Its fine-grained volcanic compositional equivalent is:', options: ['Basalt', 'Andesite', 'Rhyolite', 'Komatiite'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Granite and rhyolite are felsic compositional equivalents; granite is coarse-grained from slow cooling and rhyolite fine-grained from rapid cooling.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q034', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology — Chilled Margins', difficulty: 'medium', question: 'A basaltic dyke is much finer grained along its contact with cold country rock than at its centre. The fine-grained edge is best explained by:', options: ['Metamorphic recrystallization only at the dyke centre', 'Gravity settling of all crystals toward the wall', 'Rapid cooling at the contact producing a chilled margin', 'Complete melting of the country rock into quartz'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Heat is lost fastest at the contact, increasing nucleation relative to crystal growth and producing a fine-grained chilled margin.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q035', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology — Volcanic Textures', difficulty: 'medium', question: 'A lava contains rounded cavities that were originally gas bubbles; many are later filled by calcite and zeolite. The resulting texture is:', options: ['Amygdaloidal', 'Porphyroblastic', 'Cataclastic', 'Oolitic'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Gas vesicles in volcanic rock that later become mineral-filled are called amygdales, giving an amygdaloidal texture.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q036', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology', difficulty: 'hard', question: 'A mafic magma crystallizes and early olivine is efficiently removed from the melt. Relative to the original melt, the residual liquid generally becomes:', options: ['more silica-rich and more evolved', 'more Mg-rich because olivine removal adds Mg', 'identical in composition', 'purely carbonatitic'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Removing Mg-Fe-rich early crystals drives the residual silicate melt toward a more evolved, relatively silica-rich composition.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q037', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology — Bowen Reaction Series', difficulty: 'medium', question: 'Which sequence correctly follows the discontinuous branch of Bowen’s reaction series from higher to lower crystallization temperature?', options: ['Biotite → amphibole → pyroxene → olivine', 'Olivine → pyroxene → amphibole → biotite', 'Quartz → K-feldspar → olivine → pyroxene', 'Plagioclase → quartz → olivine → amphibole'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The discontinuous ferromagnesian branch progresses from olivine to pyroxene to amphibole to biotite as temperature falls.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q038', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology — Mantle Melting', difficulty: 'hard', question: 'Small-degree partial melting of fertile upper-mantle peridotite can generate basaltic melt even though the residue remains ultramafic. Why?', options: ['Partial melting always produces a melt identical in composition to the source', 'Only olivine melts, producing pure MgO liquid', 'Silica cannot enter a mantle-derived melt', 'Lower-melting components preferentially enter the melt, so melt composition differs from the bulk source'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Partial melting is selective rather than congruent. Components with lower effective melting temperatures partition preferentially into the melt, yielding basaltic liquid from peridotitic source.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q039', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology — Plagioclase Zoning', difficulty: 'medium', question: 'A plagioclase phenocryst has a Ca-rich core and progressively more Na-rich rims. In a normally cooling magma, this zoning most directly records:', options: ['Increasing temperature toward the rim', 'Complete absence of magmatic differentiation', 'Replacement of feldspar by quartz during weathering', 'Evolution of the melt to more sodic compositions as crystallization proceeded'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'As cooling and crystallization proceed, Ca-rich plagioclase forms earlier and the residual melt becomes relatively Na-rich, producing normal zoning.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q040', section: 'Geology/Hydrogeology Paper II', topic: 'Igneous Petrology — Magma Mixing', difficulty: 'hard', question: 'A felsic pluton contains rounded mafic enclaves, disequilibrium crystal rims and local reverse zoning in plagioclase. Taken together, these features most strongly support:', options: ['Interaction or mixing between compositionally contrasting magmas', 'Perfect equilibrium fractional crystallization in a closed homogeneous chamber', 'Weathering after complete solidification as the only process', 'Regional metamorphism without magmatism'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Mafic enclaves and disequilibrium zoning are common evidence that hotter mafic magma interacted with a cooler, more evolved magma.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q041', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology', difficulty: 'medium', question: 'Along a regional metamorphic traverse, chlorite-bearing rocks pass into biotite-, garnet- and then staurolite-bearing assemblages. The traverse most directly records:', options: ['progressive sediment sorting', 'decreasing pressure only', 'weathering of a granite', 'increasing metamorphic grade'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Successive index minerals commonly mark increasing pressure-temperature conditions and metamorphic grade.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q042', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology — Index Minerals', difficulty: 'medium', question: 'In pelitic rocks of one metamorphic belt, chlorite-bearing assemblages give way successively to biotite-, garnet- and staurolite-bearing assemblages toward the thermal maximum. This trend indicates:', options: ['Progressive decrease in temperature and pressure only', 'A transition from igneous to sedimentary deposition', 'Progressive increase in metamorphic grade', 'Chemical weathering of the same outcrop'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'In common Barrovian pelites, appearance of chlorite, biotite, garnet and staurolite occurs broadly with increasing metamorphic grade.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q043', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology — Contact Metamorphism', difficulty: 'medium', question: 'Fine-grained shale adjacent to a shallow igneous intrusion is transformed into a hard, non-foliated rock in a narrow aureole. Regional directed stress is minor. The product is most likely:', options: ['Slate', 'Hornfels', 'Blueschist', 'Mylonite'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Thermal contact metamorphism at relatively low pressure commonly produces non-foliated hornfels from fine-grained sedimentary protoliths.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q044', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology — Facies and Tectonic Setting', difficulty: 'hard', question: 'A metamorphic assemblage containing glaucophane and lawsonite formed at relatively low temperature but high pressure. Which tectonic environment is most consistent?', options: ['A mid-ocean ridge axial magma chamber', 'A shallow continental contact aureole', 'A hot desert playa', 'A subduction zone'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Blueschist-facies minerals such as glaucophane are characteristic of high-pressure, low-temperature metamorphism typical of subduction settings.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q045', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology — Gneissic Differentiation', difficulty: 'medium', question: 'A high-grade metamorphic rock shows alternating felsic quartz-feldspar bands and darker mafic bands. The banding most directly reflects:', options: ['Mineralogical segregation and recrystallization during high-grade metamorphism', 'Primary ripple lamination preserved without change', 'Only chemical weathering at the ground surface', 'Sorting by a modern river'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Gneissic banding develops through high-grade recrystallization and segregation of minerals into compositionally contrasting layers.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q046', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology', difficulty: 'hard', question: 'A pelitic rock contains sillimanite + K-feldspar and shows evidence of partial melting. Relative to a chlorite-grade slate, it records:', options: ['lower metamorphic grade', 'only surface weathering', 'diagenesis without metamorphism', 'much higher metamorphic temperature'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Sillimanite and partial melting indicate high-grade, high-temperature metamorphic conditions.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q047', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology — Isograds', difficulty: 'medium', question: 'A geologist maps the first appearance of garnet across a pelitic metamorphic terrain and joins those first-occurrence points on a map. The line is used to mark:', options: ['A metamorphic isograd', 'A shoreline', 'An igneous chill margin', 'A drainage divide'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'An isograd is a line marking the first appearance of a particular index mineral and thus a metamorphic reaction boundary in map view.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q048', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology — Protoliths', difficulty: 'medium', question: 'A nearly monomineralic metamorphic rock consists of interlocking quartz grains and breaks across grains rather than around them. Its most likely protolith is:', options: ['Limestone', 'Shale', 'Quartz-rich sandstone', 'Basalt'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Recrystallization of quartz-rich sandstone produces quartzite with interlocking quartz grains. Limestone produces marble.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q049', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology — Retrogression', difficulty: 'hard', question: 'A granulite is uplifted and cools into pressure-temperature conditions where lower-grade hydrous minerals are stable, yet much of the high-grade assemblage survives. A common reason is:', options: ['Mineral reactions are always instantaneous during cooling', 'High-grade minerals become more stable as temperature falls in every case', 'Uplift removes all chemical driving force for reaction', 'Retrograde reactions are kinetically limited, especially when fluid is scarce'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Retrogression often needs fluid and reaction pathways. Without sufficient fluid or time, metastable high-grade minerals can persist during cooling and decompression.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q050', section: 'Geology/Hydrogeology Paper II', topic: 'Metamorphic Petrology — High-Pressure Assemblages', difficulty: 'hard', question: 'A metamorphosed basalt contains abundant garnet and omphacitic clinopyroxene with little or no plagioclase. Which facies is indicated?', options: ['Greenschist facies', 'Hornfels facies', 'Eclogite facies', 'Zeolite facies'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Garnet plus omphacite is the diagnostic high-pressure assemblage of eclogite-facies metamorphism of basaltic protoliths.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q051', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology', difficulty: 'hard', question: 'Under Stokes-law conditions in the same fluid, a spherical grain of diameter 0.20 mm settles how many times as fast as a 0.10 mm grain of the same density?', options: ['4 times', '2 times', '8 times', '16 times'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Stokes settling velocity is proportional to diameter squared; (0.20/0.10)^2=4.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q052', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology — Channel Sequences', difficulty: 'medium', question: 'A channel-fill succession begins with a scoured pebble lag, passes upward into cross-bedded sand and ends with ripple-laminated fine sand and mud. The upward-fining trend most directly records:', options: ['Increasing current energy upward through the bed', 'Progressive metamorphism during burial', 'Declining flow competence as the channel fill evolved', 'A single air-fall ash eruption'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A basal coarse lag followed by progressively finer sediment is typical of waning energy during channel filling or lateral migration.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q053', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology — Paleocurrents', difficulty: 'medium', question: 'In a set of unidirectional cross-beds, foreset laminae dip consistently toward 120°. The most direct paleocurrent interpretation is transport approximately toward:', options: ['300°', '030°', '120°', '210°'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'For ordinary current-generated cross-bedding, foresets dip broadly down-current, so their mean dip azimuth is used as a paleoflow indicator.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q054', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology — Ripple Marks', difficulty: 'medium', question: 'A bedding surface carries ripples with nearly equal slopes on both sides of each crest. Which flow regime most likely formed them?', options: ['Persistent unidirectional river flow', 'Glacial ice flow', 'Debris flow without water motion', 'Oscillatory wave motion'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Symmetrical ripple marks form under reversing oscillatory currents, whereas unidirectional flow more commonly produces asymmetric ripples.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q055', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology — Way-Up Criteria', difficulty: 'medium', question: 'A turbidite bed grades from coarse sand at its base to fine silt upward. If the bed is not tectonically disturbed internally, the graded bedding indicates that stratigraphic younging is:', options: ['Toward the coarse-grained base', 'Parallel to the bedding plane only', 'Toward the finer-grained top', 'Impossible to infer from grading'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Normal grading fines upward as flow wanes. The coarse base therefore lies stratigraphically below the finer top and provides a way-up criterion.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q056', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology', difficulty: 'medium', question: 'Trough cross-beds in a fluvial sandstone consistently dip toward the southeast. The most direct paleocurrent inference is flow mainly toward the:', options: ['northwest', 'southeast', 'northeast', 'vertical direction'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'For ordinary current-generated cross-bedding, foreset dip is commonly down-current, so the dominant paleoflow was southeastward.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q057', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology — Aeolian Sand', difficulty: 'medium', question: 'A quartz-rich sandstone is exceptionally well sorted; its grains are well rounded and many have frosted surfaces. Which depositional process is most consistent?', options: ['Wind transport in an aeolian dune system', 'Deposition directly beneath glacier ice', 'Rapid proximal debris flow', 'Chemical precipitation in a cave'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Repeated grain collisions and selective wind transport commonly produce very well sorted, rounded, frosted quartz sand in dunes.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q058', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology — Sediment Maturity', difficulty: 'medium', question: 'A coarse sandstone contains abundant angular K-feldspar and quartz and occurs close to exposed granitic basement. The combination most strongly suggests:', options: ['Rapid erosion and short transport from a granitic source', 'Extremely long transport with complete feldspar destruction', 'Deep-sea chemical precipitation', 'A carbonate reef source'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Feldspar is less stable than quartz during prolonged weathering. Abundant angular feldspar near granite indicates limited chemical weathering and short transport, typical of arkosic sediment.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q059', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology — Exposure Surfaces', difficulty: 'medium', question: 'Polygonal cracks taper downward from the top of a mudstone bed and are filled by overlying sand. The cracks are best evidence for:', options: ['Continuous deep-water deposition without exposure', 'Crystal settling in a magma chamber', 'Regional metamorphic cleavage', 'Subaerial drying of wet mud before the next sediment layer was deposited'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Desiccation cracks form when muddy sediment dries and contracts at an exposed surface; downward tapering identifies the original top.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q060', section: 'Geology/Hydrogeology Paper II', topic: 'Sedimentology — Turbidites', difficulty: 'hard', question: 'A deep-marine bed begins with normally graded sand, passes upward through parallel and ripple lamination, and ends in mud. Which process best accounts for the complete vertical succession?', options: ['Growth of a coral reef in place', 'Deposition from a waning turbidity current', 'Aeolian dune migration', 'Direct lodgement beneath glacier ice'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The classic Bouma-type succession records progressive loss of competence and turbulence as a sediment-laden density current decelerates.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q061', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology', difficulty: 'medium', question: 'Fossil A ranges from 110 to 90 Ma and fossil B from 100 to 80 Ma. A bed containing both is constrained, from these ranges alone, to:', options: ['110 to 100 Ma', '90 to 80 Ma', '110 to 80 Ma with no tighter constraint', '100 to 90 Ma'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The possible age is the overlap of the two ranges: 100-90 Ma.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q062', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology — Biostratigraphic Utility', difficulty: 'medium', question: 'Two fossil species are considered for regional correlation. Species A is widespread but existed for only about 1 Myr; Species B is restricted to one basin and persisted for 30 Myr. Which is generally the better index fossil?', options: ['Species B, because long duration always gives finer time resolution', 'Species B, because geographic restriction improves regional correlation', 'Neither, because fossils cannot be used for relative dating', 'Species A, because it combines broad distribution with a short stratigraphic range'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'An effective index fossil should be geographically widespread and restricted to a relatively short interval, maximizing correlation and time resolution.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q063', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology — Paleozoic Faunas', difficulty: 'medium', question: 'A marine shale contains abundant trilobites but no younger vertebrate fossils. As a first-order age constraint, the bed must be:', options: ['Paleozoic in age', 'Cenozoic in age only', 'Quaternary in age only', 'Younger than the end-Permian extinction'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Trilobites are characteristic Paleozoic arthropods and disappeared in the end-Permian mass extinction.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q064', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology — Ammonoid Biostratigraphy', difficulty: 'medium', question: 'Why are ammonites especially useful for subdivision and correlation of many Mesozoic marine strata?', options: ['They occur only in terrestrial soils', 'They changed so slowly that one species spans the whole Mesozoic', 'They evolved rapidly and many lineages were geographically widespread', 'They are unfossilized soft-bodied organisms'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Rapid evolutionary turnover provides short biozones, while widespread marine distribution permits correlation between distant sections.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q065', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology — Foraminifera', difficulty: 'medium', question: 'A petroleum-well cutting sample contains abundant planktonic and benthic foraminifera. Why are these microfossils useful to the geologist?', options: ['They determine magnetic declination directly', 'Their assemblages can aid both biostratigraphic dating and paleoenvironmental interpretation', 'They measure rock tensile strength', 'They occur only in igneous rocks and date crystallization'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Foraminiferal species ranges support biostratigraphy, and ecological preferences of planktonic and benthic forms provide environmental information.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q066', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology', difficulty: 'medium', question: 'Two sections 500 km apart contain the same rapidly evolving, widely distributed ammonite species in narrow horizons. The strongest use of this fossil is:', options: ['high-resolution biostratigraphic correlation', 'measuring magnetic susceptibility', 'determining modern groundwater head', 'estimating grain roundness'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A widespread species with a short stratigraphic range is especially useful for correlating strata in time.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q067', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology — Taphonomy', difficulty: 'medium', question: 'In an ordinary marine burial setting with no exceptional preservation, which organism part has the highest preservation potential?', options: ['A thick calcitic shell', 'An unmineralized jellyfish body', 'A soft muscle mass', 'A thin mucus film'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Durable mineralized hard parts resist decay and destruction far better than unmineralized soft tissues under normal fossilization conditions.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q068', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology — Trace Fossils', difficulty: 'medium', question: 'A sandstone contains branching burrow systems but no preserved body of the organism that made them. What information can the burrows most directly preserve?', options: ['The exact DNA sequence of the organism', 'Only the mineral chemistry of magma', 'The absolute radiometric age of the bed', 'Behavior and interaction of the organism with the substrate'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Trace fossils such as burrows, tracks and feeding structures record biological activity rather than the organism’s body.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q069', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology — Paleoecology', difficulty: 'medium', question: 'A fossil assemblage is dominated by framework-building corals and other shallow-water carbonate organisms, with little terrigenous mud. The most likely environment was:', options: ['A deep anoxic abyssal plain', 'Warm, shallow, well-lit marine water', 'A high-altitude glacier', 'A continental desert dune field'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Reef-building corals generally require shallow photic marine settings, commonly warm and relatively clear enough for carbonate production.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q070', section: 'Geology/Hydrogeology Paper II', topic: 'Paleontology — Biohorizons', difficulty: 'medium', question: 'The first appearance of a rapidly evolving fossil species is recognized in several separated marine sections. If reworking is negligible, that first-appearance horizon can be used primarily for:', options: ['Determining present magnetic north', 'Biostratigraphic correlation between the sections', 'Measuring aquifer transmissivity', 'Calculating crystal unit-cell dimensions'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A reproducible first appearance datum can define a biohorizon that is correlated among sections, subject to ecological and diachroneity limits.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q071', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy', difficulty: 'medium', question: 'A 120 m conformable succession accumulated over 3 million years at an assumed constant net rate. The average sediment accumulation rate is:', options: ['0.025 m/Ma', '360 m/Ma', '4000 m/Ma', '40 m/Ma'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: '120 m divided by 3 Ma gives 40 m/Ma.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q072', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy — Unconformities', difficulty: 'medium', question: 'Horizontal sandstone rests erosively on older beds that were tilted to 45° before erosion. The contact is a:', options: ['Disconformity between parallel strata', 'Conformable bedding contact', 'Fault gouge zone by definition', 'Angular unconformity'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'An angular unconformity records deformation and tilting of older strata followed by erosion and deposition of younger beds at a different attitude.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q073', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy — Relative Dating', difficulty: 'medium', question: 'A sedimentary succession is upright and has not been overturned. Bed X lies directly below Bed Y. Which relative-age statement follows from superposition?', options: ['Bed X is younger than Bed Y', 'Bed X is older than Bed Y', 'The two beds must be exactly the same age', 'No relative age can ever be inferred from position'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'In an undeformed upright sedimentary sequence, lower beds were deposited before overlying beds and are therefore older.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q074', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy — Cross-Cutting Relations', difficulty: 'medium', question: 'A basaltic dyke cuts across sandstone and shale, and is itself truncated by an erosion surface overlain by conglomerate. Which unit is necessarily younger than the dyke?', options: ['The sandstone cut by the dyke', 'The shale cut by the dyke', 'The overlying conglomerate', 'Both older country-rock units only'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The dyke is younger than the rocks it cuts, but the erosion surface truncates it and the conglomerate was deposited afterward, making the conglomerate younger.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q075', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy — Facies and Time', difficulty: 'hard', question: 'A shoreline migrates basinward during regression. The same sandstone facies therefore appears progressively younger in the basinward direction. This illustrates that:', options: ['Every lithologic contact is necessarily an isochronous time plane', 'Facies can never migrate laterally', 'A lithostratigraphic facies boundary can be diachronous', 'Regression makes all sedimentary units older basinward'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Depositional environments shift through time, so the boundary between two lithofacies may cross time lines rather than represent a single age everywhere.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q076', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy', difficulty: 'medium', question: 'A volcanic ash bed dated at 82 Ma lies below a sandstone, while an ash bed dated at 78 Ma lies above it in an undeformed section. The sandstone deposition is bracketed between:', options: ['older than 82 Ma only', '82 and 78 Ma', 'younger than 78 Ma only', '82 and 160 Ma'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'By superposition, the intervening sandstone is younger than the lower 82 Ma ash and older than the upper 78 Ma ash.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q077', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy — Radiometric Bracketing', difficulty: 'medium', question: 'A fossil-bearing bed lies above a volcanic ash dated at 102±1 Ma and below another ash dated at 98±1 Ma, with no major unconformity between them. The fossil bed is most reasonably constrained to:', options: ['Older than 150 Ma', 'Approximately between 103 and 97 Ma', 'Younger than 50 Ma', 'Exactly 100.000 Ma with no uncertainty'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The lower ash provides an older bracket and the upper ash a younger bracket. Including stated uncertainties gives an approximate interval from 103 to 97 Ma.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q078', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy — Magnetostratigraphy', difficulty: 'medium', question: 'A sedimentary section records a sequence of normal and reversed magnetic-polarity intervals. Correlation with the geomagnetic polarity time scale is strongest when:', options: ['Only one polarity measurement is available with no age control', 'Every sample has been remagnetized recently', 'The section contains no stratigraphic order', 'The observed polarity pattern can be independently anchored by age or biostratigraphic control'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Polarity patterns can be non-unique over short intervals. Independent age or biostratigraphic anchors allow the local polarity sequence to be matched confidently to the global time scale.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q079', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy — Sequence Boundaries', difficulty: 'hard', question: 'A shelf succession shows incised valleys and subaerial erosion at a regional surface, followed upward by transgressive deposits. In sequence-stratigraphic terms, the erosional surface most plausibly records:', options: ['Maximum marine flooding without emergence', 'Metamorphic foliation unrelated to sedimentation', 'Relative sea-level fall and development of a sequence boundary', 'Deepening caused solely by volcanic burial'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Subaerial erosion and valley incision on a shelf are typical responses to relative sea-level fall and commonly mark a sequence boundary.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q080', section: 'Geology/Hydrogeology Paper II', topic: 'Stratigraphy — Correlation and Facies', difficulty: 'medium', question: 'Two coeval formations on opposite sides of a basin consist respectively of shoreline sandstone and offshore shale. Which statement is most accurate?', options: ['Same age requires identical lithology everywhere', 'Different lithofacies can be the same age if they were deposited simultaneously in different environments', 'Sandstone is always older than shale', 'Lithostratigraphic names are themselves numerical ages'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Walther-style lateral facies relationships allow different environments to deposit contrasting lithologies at the same time in different parts of a basin.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q081', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology', difficulty: 'medium', question: 'An orebody contains 2.0 million tonnes of ore grading 1.5% Cu. Ignoring recovery losses, contained copper is:', options: ['3,000 tonnes', '13,333 tonnes', '300,000 tonnes', '30,000 tonnes'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Contained Cu=2,000,000×0.015=30,000 tonnes.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q082', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology — Hydrothermal Veins', difficulty: 'medium', question: 'Sulfide minerals and quartz occupy a dense set of fractures around a felsic intrusion, and ore grade decreases away from the fracture network. The strongest first-order control on ore localization is:', options: ['Glacial sorting of heavy minerals in an ice sheet', 'Hydrothermal fluid flow through structurally permeable fractures', 'Regional soil formation alone', 'Direct precipitation from seawater on a modern beach'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Vein deposits form where hydrothermal fluids exploit fractures and faults; permeability structure can strongly control where ore minerals precipitate.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q083', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology — Placer Deposits', difficulty: 'medium', question: 'A stream placer contains detrital gold concentrated in lag gravels behind large boulders and on bedrock irregularities. The concentration is mainly due to:', options: ['Hydraulic sorting of dense, resistant grains', 'Complete dissolution of gold in fresh water', 'Metamorphic recrystallization of the river bed', 'Magnetic attraction of gold by quartz'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Because gold is dense and chemically resistant, flowing water can winnow lighter grains and mechanically concentrate gold in low-energy traps.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q084', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology — Supergene Enrichment', difficulty: 'hard', question: 'In a weathered copper sulfide deposit, metals are leached from the oxidized zone and reprecipitated below the water table as secondary sulfides, producing a higher-grade blanket. This is:', options: ['Magmatic differentiation', 'Contact metamorphism', 'Mechanical placer concentration', 'Supergene enrichment'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Descending oxidizing waters mobilize copper near the surface; under reducing conditions below, copper may precipitate as secondary sulfides and enrich the ore.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q085', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology — Porphyry Copper Systems', difficulty: 'medium', question: 'Exploration drilling around a porphyritic intrusion finds widespread low-grade Cu mineralization in stockwork veinlets over a very large volume rather than one narrow high-grade vein. The style is most characteristic of:', options: ['A coal seam', 'A beach placer', 'A porphyry copper deposit', 'A banded iron formation'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Porphyry systems are typically large-tonnage, comparatively low-grade deposits with disseminated and stockwork Cu mineralization centered on intrusive-hydrothermal systems.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q086', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology', difficulty: 'easy', question: 'An open pit plan requires removal of 6 million tonnes of waste to mine 2 million tonnes of ore. The stripping ratio by mass is:', options: ['1:3', '2:1', '8:1', '3:1'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Stripping ratio=waste/ore=6/2=3:1.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q087', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology — Iron Formations', difficulty: 'medium', question: 'A Precambrian unit consists of repeated thin silica-rich and iron-oxide-rich layers over a wide region. It is most appropriately classified as:', options: ['Kimberlite pipe', 'Evaporite potash seam', 'Banded iron formation', 'Lateritic bauxite profile'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Banded iron formations are chemical sedimentary rocks characterized by alternating iron-rich and silica-rich layers, especially common in Precambrian successions.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q088', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology — Skarn', difficulty: 'medium', question: 'At the contact between a granitic intrusion and limestone, the carbonate is replaced by garnet-pyroxene calc-silicate rock containing magnetite and sulfides. The deposit style is:', options: ['Placer', 'Pegmatite only', 'Bedded evaporite', 'Skarn'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Skarns form by high-temperature metasomatic reaction where intrusive fluids interact with carbonate rocks, producing calc-silicate minerals and sometimes ore.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q089', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology — Gossan Exploration', difficulty: 'medium', question: 'A rusty, iron-oxide-rich cap occurs above a zone where geophysics suggests buried sulfides. Why can such a surface feature be useful in exploration?', options: ['It proves that no sulfide minerals can occur below', 'It forms only above coal seams', 'It may be the oxidized residue of an underlying sulfide body', 'It is produced only by glacial ice'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Oxidation of iron-bearing sulfides near the surface can leave porous iron oxides and hydroxides known as gossan, which may mark concealed mineralization.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q090', section: 'Geology/Hydrogeology Paper II', topic: 'Economic Geology — Cutoff Grade', difficulty: 'hard', question: 'For the same orebody and processing route, metal price rises substantially while unit mining and treatment costs remain unchanged. Other factors equal, the economic cutoff grade would generally tend to:', options: ['Increase automatically in direct proportion to price', 'Remain fixed by mineralogy and never change', 'Become equal to the average ore grade by definition', 'Decrease, allowing lower-grade material to become economic'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Higher metal value increases revenue per unit of contained metal, so material with lower grade can meet the economic break-even threshold.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q091', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology', difficulty: 'medium', question: 'In a 1.50 m core run, sound core pieces longer than 10 cm total 1.05 m. Using the standard length criterion, RQD is:', options: ['70%', '30%', '50%', '105%'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'RQD=1.05/1.50×100=70%.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q092', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology — Dam-Site Leakage', difficulty: 'hard', question: 'A proposed reservoir is underlain by thick limestone containing sinkholes, solution cavities and open joints. Before dam construction, the most serious geologic concern is:', options: ['Excessive magnetic susceptibility of limestone', 'Formation of aeolian dunes in the reservoir', 'Seepage and leakage through karst conduits beneath or around the dam', 'Glacial abrasion of the dam crest'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Karstic limestone can contain highly transmissive conduits that bypass a dam and cause leakage or internal erosion unless thoroughly investigated and treated.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q093', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology — Tunnel Ground', difficulty: 'medium', question: 'A deep tunnel enters weak, highly deformable clay-rich rock under high overburden and the excavation perimeter continues to converge after cutting. This behavior is best managed by planning for:', options: ['Completely unsupported excavation because weak rock is self-stabilizing', 'Only a surface drainage ditch with no tunnel support', 'Squeezing ground with yielding or timely systematic support', 'Coral-reef stabilization'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Weak rock under high stress may squeeze plastically into the opening. Support must accommodate or restrain convergence and be installed with appropriate timing.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q094', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology — Rock Quality Designation', difficulty: 'medium', question: 'A 1.0 m core run yields intact pieces 22, 18, 8, 15, 5 and 12 cm long. Using the usual RQD rule that counts only pieces longer than 10 cm, the RQD is:', options: ['67%', '55%', '75%', '80%'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Pieces longer than 10 cm are 22+18+15+12=67 cm. RQD=67/100×100=67%.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q095', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology — Rock Slope Stability', difficulty: 'hard', question: 'A road cut exposes persistent bedding planes that dip 35° out of the slope face; the slope face dips 55° in nearly the same direction. If joint friction is low enough, which failure mode is particularly plausible?', options: ['Toppling on beds dipping steeply into the slope only', 'Planar sliding along bedding', 'No structurally controlled failure because bedding dips out of the slope', 'Subsidence from dissolution of halite only'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'For planar failure, a discontinuity commonly daylight outs of the slope: it dips in roughly the same direction as the slope, at less than the slope angle but sufficiently steep to overcome friction.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q096', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology', difficulty: 'easy', question: 'A slope analysis gives resisting shear force 300 kN and driving shear force 250 kN. The factor of safety is:', options: ['0.83', '1.50', '50', '1.20'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Factor of safety=resisting/driving=300/250=1.20.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q097', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology — Seismic Refraction', difficulty: 'hard', question: 'A thin low-velocity weathered layer lies beneath a higher-velocity competent layer. Why can conventional first-arrival seismic refraction fail to resolve such a buried low-velocity layer?', options: ['A slower layer beneath a faster layer may not generate the critically refracted first arrivals needed for standard interpretation', 'Low-velocity layers always produce the earliest arrivals at every distance', 'Seismic waves cannot travel through weathered material', 'Refraction methods measure only magnetic fields'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Classical refraction interpretation assumes velocity generally increases with depth; a concealed velocity inversion can therefore be missed as a hidden layer.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q098', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology — Electrical Resistivity', difficulty: 'medium', question: 'Two near-surface zones are compared by electrical resistivity. Zone A is dry, massive granite; Zone B is clay-rich and saturated with saline water. Which is expected to have the lower bulk resistivity?', options: ['Zone A, because dry quartz-rich rock is always highly conductive', 'Zone B, because conductive pore fluid and clay strongly lower resistivity', 'Both must have identical resistivity regardless of fluid', 'Neither can conduct electric current under any condition'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Ionic conduction through saline pore water and surface conduction associated with clays commonly make saturated clay-rich material much less resistive than dry competent granite.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q099', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology — Expansive Soils', difficulty: 'medium', question: 'A low-rise structure is planned on clay that swells strongly when wetted and shrinks on drying. Which foundation strategy most directly reduces damage from seasonal near-surface volume change?', options: ['Founding on elements that extend below the active moisture zone, together with moisture control', 'Using very shallow isolated footings only within the most active soil', 'Encouraging large wetting-drying cycles around the foundation', 'Removing all drainage so ponding occurs beside the building'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Expansive-soil movement is concentrated in the active zone. Deep or under-reamed foundations and controlled site drainage reduce transfer of seasonal heave and shrinkage to the structure.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q100', section: 'Geology/Hydrogeology Paper II', topic: 'Applied & Engineering Geology — Rock-Mass Quality', difficulty: 'medium', question: 'Two tunnel headings are in the same intact rock type. Heading X has closely spaced slickensided clay-filled joints with groundwater inflow; Heading Y has widely spaced rough, unfilled, dry joints. Which heading should generally have the better rock-mass quality?', options: ['Heading X', 'Heading Y', 'Both are necessarily identical because intact lithology is the same', 'Quality cannot depend on discontinuities or groundwater'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Engineering rock-mass quality depends strongly on joint spacing and condition and on groundwater. Wider, rough, unfilled, dry joints generally favor better stability.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q101', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology', difficulty: 'medium', question: 'Groundwater flows through a 100 m² cross-section with hydraulic conductivity 10 m/day and hydraulic gradient 0.02. Darcy discharge is:', options: ['2 m³/day', '20 m³/day', '50 m³/day', '200 m³/day'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Q=K i A=10×0.02×100=20 m³/day.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q102', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology — Darcy Flow', difficulty: 'medium', question: 'Groundwater flows through a saturated sand aquifer with hydraulic conductivity 10 m/day, hydraulic gradient 0.005 and cross-sectional area 200 m². Darcy discharge is:', options: ['10 m³/day', '1 m³/day', '100 m³/day', '1,000 m³/day'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Darcy’s law gives Q=K i A=10×0.005×200=10 m³/day.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q103', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology — Specific Yield', difficulty: 'hard', question: 'An unconfined aquifer has specific yield 0.18. If the water table declines uniformly by 2.0 m beneath an area of 1.0 km², the approximate volume of water released from storage is:', options: ['36,000 m³', '180,000 m³', '360,000 m³', '2,000,000 m³'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Released volume≈S_y A Δh=0.18×1,000,000×2=360,000 m³.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q104', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology — Transmissivity', difficulty: 'medium', question: 'A confined aquifer is 30 m thick and has hydraulic conductivity 20 m/day. Its transmissivity is:', options: ['50 m²/day', '200 m²/day', '6,000 m²/day', '600 m²/day'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Transmissivity T=Kb=20×30=600 m²/day.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q105', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology — Hydraulic Head', difficulty: 'medium', question: 'The measuring point of a piezometer is at elevation 100 m above datum, and the water level in the tube stabilizes at elevation 112 m. At the measuring point, the pressure head is:', options: ['100 m', '12 m', '112 m', '212 m'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Total head is the water-level elevation, 112 m. Pressure head at the measuring point is 112−100=12 m.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q106', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology', difficulty: 'easy', question: 'A confined aquifer has hydraulic conductivity 15 m/day and saturated thickness 20 m. Its transmissivity is:', options: ['0.75 m²/day', '35 m²/day', '300 m²/day', '750 m²/day'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'T=Kb=15×20=300 m²/day.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q107', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology — Pumping Response', difficulty: 'medium', question: 'A pumping well in a homogeneous unconfined aquifer has reached quasi-steady drawdown. Piezometric contours form closed curves of progressively lower head toward the well. Groundwater flow near the well is therefore:', options: ['Radially outward from the well at all depths', 'Radially inward toward the well', 'Exactly parallel to every contour line', 'Absent because contours are closed'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Groundwater flows from higher to lower hydraulic head approximately normal to head contours, so a pumping cone produces inward flow toward the well.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q108', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology — Leaky Confined Aquifers', difficulty: 'hard', question: 'During a long pumping test, drawdown in a confined aquifer becomes smaller than predicted by a nonleaky Theis model because water is transmitted through the overlying semiconfining layer. The aquifer behavior is:', options: ['Perfectly impermeable confined', 'Perched only', 'Leaky (semiconfined)', 'Unsaturated vadose flow only'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Leakage through an aquitard provides additional recharge to the pumped aquifer and alters the drawdown-time response relative to an ideally confined system.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q109', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology — Coastal Freshwater Lenses', difficulty: 'hard', question: 'In the simplest Ghyben-Herzberg approximation, the freshwater table on a coastal island stands 1.5 m above sea level. Taking the fresh-salt density contrast in the usual way, the freshwater-saltwater interface is about how far below sea level?', options: ['1.5 m', '15 m', '600 m', '60 m'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The approximation places the interface roughly 40 times the freshwater head below sea level: z≈40h=40×1.5=60 m.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q110', section: 'Geology/Hydrogeology Paper II', topic: 'Hydrogeology — Groundwater Contamination', difficulty: 'medium', question: 'Shallow unconfined wells beneath intensively fertilized farmland show high nitrate, while nearby deeper confined wells remain low in nitrate. Which interpretation is most consistent?', options: ['Nitrate must originate from deep mantle fluids', 'The confined aquifer is necessarily more exposed to surface recharge', 'A near-surface contaminant source is reaching the more vulnerable unconfined aquifer', 'Fertilizer use cannot affect groundwater chemistry'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Nitrate from agricultural sources readily leaches with recharge. An unconfined aquifer has less protection from surface inputs than a well-confined deeper aquifer.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q111', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS', difficulty: 'medium', question: 'A raster has 30 m × 30 m pixels. An area covers exactly 100×100 pixels. Its ground area is:', options: ['9 km²', '0.9 km²', '30 km²', '90 km²'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Each pixel is 900 m²; 10,000 pixels cover 9,000,000 m²=9 km².', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q112', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS — Georeferencing Accuracy', difficulty: 'medium', question: 'During georeferencing of a geological map, one ground-control point has residual errors of 3 m in easting and 4 m in northing. The magnitude of its positional residual is:', options: ['3 m', '4 m', '7 m', '5 m'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'The residual magnitude is the Euclidean distance √(3²+4²)=5 m.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q113', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS — Spatial Resolution', difficulty: 'medium', question: 'Two otherwise comparable satellite images have pixel sizes of 10 m and 30 m. Which statement is correct for mapping narrow surface features?', options: ['The 30 m image always resolves smaller features because the pixels are larger', 'Pixel size has no relation to spatial detail', 'The 10 m image generally resolves smaller features because its spatial resolution is finer', 'Both images necessarily contain identical spatial detail'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Smaller ground sampling distance provides finer spatial resolution, so a 10 m pixel image can generally distinguish smaller features than a 30 m image.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q114', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS — Radiometric Resolution', difficulty: 'medium', question: 'A sensor records each band with 12-bit radiometric depth instead of 8-bit depth. How many possible digital-number levels are available in the 12-bit data?', options: ['256', '1024', '8192', '4096'], correctIndex: 3, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'An n-bit sensor can represent 2^n levels. For 12 bits, 2^12=4096 levels, allowing finer discrimination of brightness differences than 8-bit data.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q115', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS — Classification Accuracy', difficulty: 'hard', question: 'A supervised land-cover classification is checked against 100 independent reference points. The confusion matrix shows 88 points on its main diagonal. Ignoring class weighting, the overall accuracy is:', options: ['12%', '88%', '44%', '100%'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Overall accuracy is the number of correctly classified reference samples divided by the total: 88/100=88%.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q116', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS', difficulty: 'medium', question: 'A pixel has NIR reflectance 0.48 and red reflectance 0.12. Its NDVI is:', options: ['0.20', '0.36', '0.60', '0.80'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'NDVI=(NIR-red)/(NIR+red)=0.36/0.60=0.60.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q117', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS — Digital Elevation Models', difficulty: 'medium', question: 'A GIS analyst has a gridded digital elevation model and wants maps of terrain steepness and downslope direction. Which two derivatives should be calculated?', options: ['Slope and aspect', 'Buffer and dissolve', 'Geocode and address match', 'Hue and saturation only'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A DEM stores elevation values. Local gradients derived from neighboring cells give slope magnitude and aspect, the direction of steepest descent.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q118', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS — Georeferencing', difficulty: 'medium', question: 'A scanned geological map is fitted to projected coordinates using ground-control points. One control point has a residual far larger than all others. Before accepting the transformation, the best action is to:', options: ['Ignore all residuals because georeferencing cannot be assessed', 'Check that point for misidentification or digitizing error and refit if necessary', 'Delete the coordinate system from the GIS', 'Convert the raster to grayscale only'], correctIndex: 1, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A large isolated residual often signals a bad control point or digitizing mistake. Control points should be checked before a final transformation is accepted.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q119', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS — Supervised Classification', difficulty: 'medium', question: 'To classify multispectral pixels into lithologic classes using a supervised algorithm, the analyst must first provide:', options: ['Representative labelled training samples for the target classes', 'Only an unlabelled histogram with no class information', 'A contour interval but no imagery', 'A list of map-sheet names only'], correctIndex: 0, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'Supervised classification learns class signatures from samples whose class membership is supplied by the analyst.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
  { id: 'b14-002-geo-q120', section: 'Geology/Hydrogeology Paper II', topic: 'Remote Sensing & GIS — Proximity Analysis', difficulty: 'medium', question: 'A groundwater-protection study must identify every mapped well lying within 500 m of a contaminated stream. Which GIS workflow is most direct?', options: ['Interpolate a DEM from the wells only', 'Convert all wells to raster without using distance', 'Create a 500 m buffer around the stream and select wells intersecting the buffer', 'Perform a map projection change and stop'], correctIndex: 2, answerType: 'mcq', marks: 2.5, negativeMarking: 0.8333333333333334, explanation: 'A buffer constructs the specified distance zone around the stream; a spatial selection then identifies well points that fall inside that zone.', source: { kind: 'original', reference: 'UPSC Combined Geo-Scientist (Preliminary) Examination, 2027', url: 'https://www.upsc.gov.in/examinations/Combined%20Geo-Scientist%20%28Preliminary%29%20Examination%2C%202027', checkedOn: '2026-09-10' } },
];
